];

const labIdx = ((jsDay >= 1 && jsDay <= 5 ? jsDay - 1 : 0) + runCounter) % dailyLabs.length;
const lab = dailyLabs[labIdx];

if (!store.pillarTopicCursor || typeof store.pillarTopicCursor !== 'object') {
  store.pillarTopicCursor = {};
}
if (!Array.isArray(store.usedTopicsHistory)) {
  store.usedTopicsHistory = [];
}

const usedSet = new Set(store.usedTopicsHistory);
let cursor = typeof store.pillarTopicCursor[lab.key] === 'number' ? store.pillarTopicCursor[lab.key] : 0;

let selectedTopic = lab.topics[cursor % lab.topics.length];
for (let offset = 0; offset < lab.topics.length; offset++) {
  const candidate = lab.topics[(cursor + offset) % lab.topics.length];
  if (!usedSet.has(candidate)) {
    selectedTopic = candidate;
    cursor = (cursor + offset + 1) % lab.topics.length;
    break;
  }
}
store.pillarTopicCursor[lab.key] = cursor;
store.usedTopicsHistory = [...store.usedTopicsHistory.slice(-80), selectedTopic];

return [{
  json: {
    pillarKey: lab.key,
    pillar: lab.pillar,
    pillarBadge: lab.pillarBadge,
    accentColor: lab.accentColor,
    voiceId: lab.voiceId,
    fallbackQuery: lab.fallbackQuery,
    topic: selectedTopic,
    recentUsedTopics: store.usedTopicsHistory.slice(-25),
    targetDuration: 52,
    numClips: 6,
    platform: 'Instagram Reels & YouTube Shorts'
  }
}];

const cfg = $('Select Topic & Config').first().json;
const rawContent = ($input.first().json.message?.content || '{}')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

let parsed = {};
try {
  parsed = JSON.parse(rawContent);
} catch (e) {
  parsed = {};
}

const numClips = 6;
let sceneLines = Array.isArray(parsed.sceneLines) && parsed.sceneLines.length === 6
  ? parsed.sceneLines.map(s => String(s || '').trim())
  : [];

if (sceneLines.length < 6) {
  const fullText = [parsed.hook, parsed.mainContent, parsed.cta].filter(Boolean).join(' ') || cfg.topic;
  const words = fullText.split(/\s+/).filter(Boolean);
  const chunk = Math.max(1, Math.ceil(words.length / 6));
  sceneLines = [];
  for (let i = 0; i < 6; i++) {
    let seg = words.slice(i * chunk, (i + 1) * chunk).join(' ').trim();
    if (seg && !/[.?!]$/.test(seg)) seg += '.';
    sceneLines.push(seg || 'Try this simple science-backed habit today.');
  }
}

const fullVoiceoverText = sceneLines.join(' ');

let flatHashtags = ['#lifehacks', '#dailyhabits', '#selfimprovement', '#brainhacks', '#productivitytips', '#learnsomethingnew', '#sciencebacked', '#bytefyi'];
if (parsed.hashtags) {
  const combined = [
    ...(parsed.hashtags.pillar || []),
    ...(parsed.hashtags.platform || []),
    ...(parsed.hashtags.engagement || [])
  ].filter(Boolean);
  if (combined.length >= 4) flatHashtags = combined;
}

const sceneCards = Array.isArray(parsed.sceneCards) && parsed.sceneCards.length === 6
  ? parsed.sceneCards
  : [];

const cheatSheetSteps = Array.isArray(parsed.cheatSheetSteps) && parsed.cheatSheetSteps.length === 3
  ? parsed.cheatSheetSteps
  : (sceneCards.slice(2, 5).map(c => c?.takeaway).filter(Boolean));

const dailyChallenge = String(parsed.dailyChallenge || 'Pick Step #1 and test it once in the next 24 hours!').trim();
const title = String(parsed.title || cfg.topic).slice(0, 65).trim();
const heroHeadline = String(parsed.heroHeadline || '3 SCIENCE-BACKED\nDAILY UPGRADES').replace(/\\[nN]/g, '\n').trim();
const heroSubhead = String(parsed.heroSubhead || cfg.topic).trim();
const clipTerms = Array.isArray(parsed.clipSearchTerms) ? parsed.clipSearchTerms : [];

const instagramCaption = `${title}\n\n${heroSubhead}\n\n📌 60-Second Cheat Sheet:\n1️⃣ ${cheatSheetSteps[0] || 'Step 1'}\n2️⃣ ${cheatSheetSteps[1] || 'Step 2'}\n3️⃣ ${cheatSheetSteps[2] || 'Step 3'}\n\n🎯 24-Hour Challenge: ${dailyChallenge}\n\nSave this post for later & follow @bytefyi for tomorrow's daily life upgrade!\n\n${flatHashtags.join(' ')}`;

const newItems = [];
for (let i = 0; i < numClips; i++) {
  newItems.push({
    json: {
      ...cfg,
      title,
      heroHeadline,
      heroSubhead,
      hook: sceneLines[0],
      mainContent: sceneLines.slice(1, 5).join(' '),
      cta: sceneLines[5],
      fullVoiceoverText,
      sceneLines,
      sceneCards,
      cheatSheetSteps,
      dailyChallenge,
      hashtags: flatHashtags,
      instagramCaption,
      clipNumber: i + 1,
      mainContentSegment: sceneLines[i],
      aiClipSearchTerm: String(clipTerms[i] || '').trim(),
      falPrompt: sceneLines[i],
      visualDirection: heroSubhead
    }
  });
}

return newItems;

