const videoUrls = [];
const loopData = $('Loop Over Segments').all();
for (const item of loopData) {
  if (item.json.video && item.json.video.url) {
    videoUrls.push(item.json.video.url);
  }
}

const d = $('Extract Script Array').first().json;
const durInfo = $('Check Audio Length').first().json;
const audioUrl = $('GCS - Upload Audio').first().json.mediaLink;

return [{
  json: {
    mode: 'daily_life_masterclass',
    pillar: d.pillar,
    pillarBadge: d.pillarBadge,
    accentColor: d.accentColor,
    title: d.title,
    heroHeadline: d.heroHeadline,
    heroSubhead: d.heroSubhead,
    sceneLines: d.sceneLines,
    sceneCards: d.sceneCards,
    cheatSheetSteps: d.cheatSheetSteps,
    dailyChallenge: d.dailyChallenge,
    video_urls: videoUrls,
    videoDurations: durInfo.videoDurations,
    totalAudioDuration: durInfo.totalAudioDuration,
    audio_url: audioUrl
  }
}];

const audioContent = $json.audioContent || $json.audio_base64;
const binaryData = Buffer.from(audioContent, 'base64');
const fileName = `daily_life_masterclass_${Date.now()}.mp3`;

return [{
  json: {
    ...$json,
    fileName,
    audioContent: undefined,
    audio_base64: undefined
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'audio/mpeg',
      fileName
    }
  }
}];

// Pass-through: each item already carries video.url from Pick Pexels Clip.
// (Previously wrote to $vars, which is read-only in n8n.)
console.log('Clip', $json.clipNumber, '->', $json.video && $json.video.url);
return $input.all();

const inputData = $input.first().json;
const audioContent = inputData.audio_base64 || inputData.audioContent;

if (!audioContent) {
  throw new Error('No audio_base64 or audioContent found from ElevenLabs TTS');
}

const binaryData = Buffer.from(audioContent, 'base64');
// ElevenLabs mp3_44100_128 is 128kbps = 16,000 bytes per second
const exactAudioSeconds = binaryData.length / 16000;
const totalAudioDuration = Number(Math.max(28, exactAudioSeconds + 0.8).toFixed(2));

const scriptItem = $('Extract Script Array').first().json;
const sceneLines = Array.isArray(scriptItem.sceneLines) && scriptItem.sceneLines.length === 6
  ? scriptItem.sceneLines
  : ['Scene 1', 'Scene 2', 'Scene 3', 'Scene 4', 'Scene 5', 'Scene 6'];

function speechWeight(text) {
  const s = String(text || '').trim();
  if (!s) return 10;
  const syllables = (s.toLowerCase().match(/[aeiouy]{1,2}/g) || []).length;
  const pauses = (s.match(/[,.;:!?—-]/g) || []).length * 2.2;
  return Math.max(8, syllables + pauses);
}

const weights = sceneLines.map(speechWeight);
const totalWeight = weights.reduce((a, b) => a + b, 0) || 60;

const videoDurations = weights.map(w => Number(Math.max(4.2, (w / totalWeight) * totalAudioDuration).toFixed(2)));
const sumFirst5 = videoDurations.slice(0, 5).reduce((a, b) => a + b, 0);
videoDurations[5] = Number(Math.max(4.5, totalAudioDuration - sumFirst5).toFixed(2));
const finalDuration = Number(videoDurations.reduce((a, b) => a + b, 0).toFixed(2));

return [{
  json: {
    ...scriptItem,
    audioContent,
    audioSize: binaryData.length,
    totalAudioDuration: finalDuration,
    videoDurations,
    totalVideos: 6,
    durationStatus: 'good',
    targetDuration: finalDuration
  }
}];

const item = $input.first();
const scriptData = $('Extract Script Array').first().json;
const rawTitle = scriptData.title || item.json.title || 'Daily Life Upgrade';

const safe = rawTitle
  .replace(/[:]/g, ' ')
  .replace(/\r?\n|\r/g, ' ')
  .replace(/[^\p{L}\p{N}\p{P}\p{Z}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 58);

const finalTitle = `${safe} #LifeHacks #DailyHabits #ScienceBacked #Shorts`;

return [{
  json: {
    title: finalTitle,
    description: scriptData.instagramCaption || finalTitle
  },
  binary: item.binary
}];

const STOP = new Set(['about','above','after','again','against','also','because','been','before','being','below','between','both','cannot','could','does','doing','down','during','each','even','ever','every','from','further','have','having','here','into','itself','just','like','little','make','makes','many','more','most','much','must','need','never','next','only','other','ought','over','really','right','same','should','some','such','than','that','their','theirs','them','then','there','these','they','thing','things','this','those','through','today','under','until','very','want','what','when','where','which','while','will','with','would','your','yours','yourself','youre','dont','lets','heres','thats','first','finally','start','great','time','know','keep','take','better','best','since','still','ready','video','follow']);

const cfg = $('Select Topic & Config').first().json;
const fallbackQuery = cfg.fallbackQuery || 'person working morning sunlight';

return $input.all().map(item => {
  const aiTerm = String(item.json.aiClipSearchTerm || '').replace(/[^a-zA-Z0-9\s-]/g, ' ').replace(/\s+/g, ' ').trim();
  const text = (item.json.mainContentSegment || item.json.title || '').toLowerCase();
  const words = text.replace(/[^a-z\s']/g, ' ').split(/\s+/)
    .map(w => w.replace(/'/g, ''))
    .filter(w => w.length >= 4 && !STOP.has(w));
  const keywordQuery = [...new Set(words)].slice(0, 3).join(' ');
  const pexelsQuery = aiTerm || keywordQuery || fallbackQuery;
  return {
    json: {
      ...item.json,
      pexelsQuery,
      querySource: aiTerm ? 'openai' : (keywordQuery ? 'keywords' : 'pillar'),
      fallbackQuery
    }
  };
});

// Choose one portrait Pexels clip per segment, avoiding repeats within the same day
const q = $('Build Pexels Query').first().json;
const primary = $('Pexels - Search Clip').first().json.videos || [];
const fallback = $('Pexels - Search Fallback').first().json.videos || [];

const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (store.pexelsDay !== today) { store.pexelsDay = today; store.pexelsUsed = []; }
const used = new Set(store.pexelsUsed);

const usable = v => v.duration >= 8 && !used.has(v.id) && (v.video_files || []).some(f => f.height > f.width);
let pool = primary.filter(usable);
let source = 'primary';
if (!pool.length) { pool = fallback.filter(usable); source = 'fallback'; }
if (!pool.length) { pool = primary.concat(fallback).filter(v => (v.video_files || []).length); source = 'any'; }
if (!pool.length) throw new Error(`No Pexels videos found for "${q.pexelsQuery}" or "${q.fallbackQuery}"`);

const video = pool.slice(0, 8)[Math.floor(Math.random() * Math.min(8, pool.length))];
const portrait = video.video_files.filter(f => f.height > f.width && f.file_type === 'video/mp4');
const files = portrait.length ? portrait : video.video_files;
// Prefer 720x1280 (good quality, smaller download), otherwise closest to it
const file = files.slice().sort((a, b) => Math.abs(a.height - 1280) - Math.abs(b.height - 1280))[0];

store.pexelsUsed.push(video.id);

return [{ json: {
  ...q,
  video: { url: file.link, width: file.width, height: file.height, duration: video.duration },
  pexels: { id: video.id, page: video.url, author: video.user && video.user.name, source }
} }];
